// lps[i] = length of the longest proper prefix of p[0..i] that is also a suffix
vector<int> buildLps(const string& p) {
    vector<int> lps(p.size(), 0);
    int len = 0;
    for (size_t i = 1; i < p.size(); ) {
        if (p[i] == p[len]) lps[i++] = ++len;
        else if (len)       len = lps[len - 1];   // fall back, do NOT reset to 0
        else                lps[i++] = 0;
    }
    return lps;
}

int strStr(const string& s, const string& p) {
    if (p.empty()) return 0;
    vector<int> lps = buildLps(p);
    for (size_t i = 0, j = 0; i < s.size(); ) {
        if (s[i] == p[j]) {
            ++i; ++j;
            if (j == p.size()) return (int)(i - j);
        }
        else if (j) j = lps[j - 1];               // reuse the matched prefix
        else        ++i;
    }
    return -1;
}

