def build_lps(p: str) -> list[int]:
    """lps[i] = length of the longest proper prefix of p[:i+1] that is also a suffix."""
    lps = [0] * len(p)
    length = 0
    i = 1
    while i < len(p):
        if p[i] == p[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length:
            length = lps[length - 1]      # fall back, do NOT reset to 0
        else:
            lps[i] = 0
            i += 1
    return lps


def str_str(s: str, p: str) -> int:
    if not p:
        return 0
    lps = build_lps(p)
    i = j = 0
    while i < len(s):
        if s[i] == p[j]:
            i += 1
            j += 1
            if j == len(p):
                return i - j
        elif j:
            j = lps[j - 1]                # reuse the matched prefix
        else:
            i += 1
    return -1

