vector<int> findAnagrams(const string& s, const string& p) {
    vector<int> out;
    if (s.size() < p.size()) return out;
    int delta[26] = {0}, wrong = 0;
    for (char c : p) ++delta[c - 'a'];
    for (int d : delta) if (d) ++wrong;          // letters not yet balanced

    auto adjust = [&](int idx, int step) {       // step is +1 (leaving) or -1 (entering)
        if (delta[idx] == 0) ++wrong;            // was balanced, now is not
        delta[idx] += step;
        if (delta[idx] == 0) --wrong;            // just became balanced
    };

    for (size_t i = 0; i < s.size(); ++i) {
        adjust(s[i] - 'a', -1);                          // char enters the window
        if (i >= p.size()) adjust(s[i - p.size()] - 'a', +1);   // char leaves
        if (i + 1 >= p.size() && wrong == 0) out.push_back((int)(i + 1 - p.size()));
    }
    return out;
}

