    out = []
    if len(s) < len(p):
        return out
    delta = [0] * 26
    for c in p:
        delta[ord(c) - 97] += 1
    wrong = sum(1 for d in delta if d)      # letters not yet balanced

    def adjust(idx, step):                  # step is +1 (leaving) or -1 (entering)
        nonlocal wrong
        if delta[idx] == 0:
            wrong += 1                      # was balanced, now is not
        delta[idx] += step
        if delta[idx] == 0:
            wrong -= 1                      # just became balanced

    for i, c in enumerate(s):
        adjust(ord(c) - 97, -1)                        # char enters the window
        if i >= len(p):
            adjust(ord(s[i - len(p)]) - 97, +1)        # char leaves
        if i + 1 >= len(p) and wrong == 0:
            out.append(i + 1 - len(p))
    return out

