def check_inclusion(p: str, s: str) -> bool:
    if len(p) > len(s):
        return False                    # cannot possibly fit
    delta = [0] * 26
    for c in p:
        delta[ord(c) - 97] += 1
    wrong = sum(1 for d in delta if d)

    def adjust(idx, step):
        nonlocal wrong
        if delta[idx] == 0:
            wrong += 1
        delta[idx] += step
        if delta[idx] == 0:
            wrong -= 1

    for i, c in enumerate(s):
        adjust(ord(c) - 97, -1)
        if i >= len(p):
            adjust(ord(s[i - len(p)]) - 97, +1)
        if i + 1 >= len(p) and wrong == 0:
            return True                 # first hit wins
