string reverseWords(string s) {
    // PASS 1: squeeze leading/trailing/repeated spaces with a write pointer
    int write = 0;
    for (int read = 0; read < (int)s.size(); ) {
        while (read < (int)s.size() && s[read] == ' ') ++read;         // skip spaces
        while (read < (int)s.size() && s[read] != ' ') s[write++] = s[read++];
        while (read < (int)s.size() && s[read] == ' ') ++read;
        if (read < (int)s.size()) s[write++] = ' ';                    // one separator
    }
    s.resize(write);

    // PASS 2: reverse the whole buffer -- words are now in the right ORDER, spelled backwards
    reverse(s.begin(), s.end());

    // PASS 3: reverse each word in place to fix the spelling
    int start = 0;
    for (int i = 0; i <= (int)s.size(); ++i)
        if (i == (int)s.size() || s[i] == ' ') {
            reverse(s.begin() + start, s.begin() + i);
            start = i + 1;
        }
    return s;
}

