def reverse_words(s: str) -> str:
    a = list(s)
    # PASS 1: squeeze leading/trailing/repeated spaces with a write pointer
    write = read = 0
    n = len(a)
    while read < n:
        while read < n and a[read] == ' ':
            read += 1
        while read < n and a[read] != ' ':
            a[write] = a[read]; write += 1; read += 1
        while read < n and a[read] == ' ':
            read += 1
        if read < n:
            a[write] = ' '; write += 1        # exactly one separator
    a = a[:write]

    # PASS 2: reverse everything -- correct ORDER, backwards spelling
    a.reverse()

    # PASS 3: reverse each word back to fix the spelling
    start = 0
    for i in range(len(a) + 1):
        if i == len(a) or a[i] == ' ':
            a[start:i] = reversed(a[start:i])
            start = i + 1
    return "".join(a)

