string multiply(const string& a, const string& b) {
    if (a == "0" || b == "0") return "0";        // avoid a buffer of all zeros
    int m = (int)a.size(), n = (int)b.size();
    vector<int> buf(m + n, 0);                    // product has at most m+n digits
    for (int i = m - 1; i >= 0; --i)
        for (int j = n - 1; j >= 0; --j) {
            int mul = (a[i] - '0') * (b[j] - '0');
            int low = i + j + 1, high = i + j;    // low holds units, high the carry
            int sum = mul + buf[low];
            buf[low] = sum % 10;
            buf[high] += sum / 10;                // carry accumulates, resolved later
        }
    string out;
    for (int d : buf)
        if (!(out.empty() && d == 0)) out += char('0' + d);   // strip leading zeros
    return out.empty() ? "0" : out;
}

