string under1000(int n) {
    if (n == 0)   return "";
    if (n < 20)   return BELOW20[n];
    if (n < 100) {
        string out = TENS[n / 10];
        if (n % 10) out += " " + BELOW20[n % 10];
        return out;
    }
    string out = BELOW20[n / 100] + " Hundred";
    if (n % 100) out += " " + under1000(n % 100);
