string numberToWords(int num) {
    if (num == 0) return "Zero";                 // the ONE special case
    static const vector<string> SCALES = {"", " Thousand", " Million", " Billion"};
    string out;
    int scale = 0;
    while (num) {
        int chunk = num % 1000;
        if (chunk) {
            string part = under1000(chunk) + SCALES[scale];
            out = part + (out.empty() ? "" : " " + out);   // no double spaces
        }
        num /= 1000;
        ++scale;
    }
    return out;
}

