string minWindow(const string& s, const string& t) {
    if (s.empty() || t.empty() || s.size() < t.size()) return "";
    unordered_map<char,int> need;
    for (char c : t) ++need[c];
    int required = (int)need.size();      // distinct chars still to satisfy
    int formed = 0;

    unordered_map<char,int> window;
    int bestLen = INT_MAX, bestLo = 0, l = 0;
    for (int r = 0; r < (int)s.size(); ++r) {
        char c = s[r];
        if (need.count(c) && ++window[c] == need[c]) ++formed;   // exactly satisfied

        while (formed == required) {                 // shrink while still covered
            if (r - l + 1 < bestLen) { bestLen = r - l + 1; bestLo = l; }
            char d = s[l++];
            if (need.count(d) && window[d]-- == need[d]) --formed;
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestLo, bestLen);
}

