def min_window(s: str, t: str) -> str:
    if not s or not t or len(s) < len(t):
        return ""
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    required = len(need)          # distinct chars still to satisfy
    formed = 0

    window = {}
    best_len, best_lo, l = float('inf'), 0, 0
    for r, c in enumerate(s):
        if c in need:
            window[c] = window.get(c, 0) + 1
            if window[c] == need[c]:
                formed += 1                   # exactly satisfied
        while formed == required:             # shrink while still covered
            if r - l + 1 < best_len:
                best_len, best_lo = r - l + 1, l
            d = s[l]
            l += 1
            if d in need:
                if window[d] == need[d]:
                    formed -= 1
                window[d] -= 1
    return "" if best_len == float('inf') else s[best_lo:best_lo + best_len]
